import {missions,MU,RADIUS,DT,launch,step,trace,gates,energy} from './physics.mjs';
const $=id=>document.getElementById(id),canvas=$('space'),ctx=canvas.getContext('2d');
let index=0,s=launch(missions[0],88,-90),running=false,paused=false,predict=true,hits=[false,false,false],path=[],preview=[],lastPath=[],targets=gates(missions[0]),acc=0,last=0,history=[];
function values(){return [+$('speed').value,+$('angle').value]}
function telemetry(){ $('liveSpeed').textContent=Math.hypot(s.vx,s.vy).toFixed(1);$('altitude').textContent=Math.max(0,Math.hypot(s.x,s.y)-RADIUS).toFixed(0);$('clock').textContent=`T + ${s.t.toFixed(1).padStart(4,'0')} s`;$('energyLabel').textContent=energy(s)<0?'BOUND TRAJECTORY':'ESCAPE ENERGY';$('score').textContent=`${hits.filter(Boolean).length} / 3 gates`;hits.forEach((h,i)=>$('g'+i).classList.toggle('hit',h));}
function reset(){if(path.length)lastPath=path.slice();running=false;paused=false;hits=[false,false,false];path=[];history=[];s=launch(missions[index],...values());preview=trace(missions[index],...values());$('launch').disabled=false;$('pause').disabled=true;$('pause').textContent='Pause';$('speed').disabled=false;$('angle').disabled=false;$('phase').textContent='READY TO LAUNCH';$('toast').textContent='Set your trajectory. The dotted line is your prediction.';telemetry();draw();}
function update(){ $('speedVal').textContent=(+$('speed').value).toFixed(1);$('angleVal').textContent=$('angle').value+'°';reset();}
function start(){reset();running=true;$('launch').disabled=true;$('pause').disabled=false;$('speed').disabled=true;$('angle').disabled=true;$('phase').textContent='PROBE IN FLIGHT';$('toast').textContent='One impulse. Let gravity do the rest.';}
function pause(){if(!running)return;paused=!paused;$('pause').textContent=paused?'Resume':'Pause';$('phase').textContent=paused?'FLIGHT PAUSED':'PROBE IN FLIGHT';}
function setMission(i){index=i;targets=gates(missions[i]);lastPath=[];path=[];$('mission').textContent=missions[i].name;$('speed').value=missions[i].v-3;$('angle').value=missions[i].angle;$('hintText').hidden=true;document.querySelectorAll('[data-m]').forEach(b=>{const on=+b.dataset.m===i;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on)});update();}
function finish(message){running=false;$('launch').disabled=false;$('pause').disabled=true;$('speed').disabled=false;$('angle').disabled=false;$('phase').textContent=hits.every(Boolean)?'MISSION COMPLETE':'FLIGHT COMPLETE';$('toast').textContent=message;}
function tick(){s=step(s);if(Math.round(s.t/DT)%5===0){path.push({...s});history.push(Math.hypot(s.vx,s.vy));}targets.forEach((g,i)=>{if(Math.hypot(g.x-s.x,g.y-s.y)<24)hits[i]=true});if(hits.every(Boolean))finish('All three gates. Beautiful flying. Try the next mission.');else if(s.status==='impact')finish('Surface contact. Try more sideways speed.');else if(s.status==='escaped')finish('You escaped. Dial back the launch speed.');else if(s.status==='finished')finish('Flight complete. Adjust one variable and try again.');}
function draw(){const box=canvas.getBoundingClientRect(),w=box.width,h=box.height,dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const scale=Math.min(w/770,h/730),cx=w/2,cy=h/2;ctx.save();ctx.translate(cx,cy);ctx.scale(scale,scale);
 ctx.strokeStyle='#253541';ctx.lineWidth=.6;for(let a=-500;a<=500;a+=50){ctx.beginPath();ctx.moveTo(a,-500);ctx.lineTo(a,500);ctx.stroke();ctx.beginPath();ctx.moveTo(-500,a);ctx.lineTo(500,a);ctx.stroke()}for(let i=0;i<85;i++){const x=((i*137.53)%950)-475,y=((i*79.77)%750)-375;ctx.fillStyle=i%3?'#66828b70':'#b5d4d7';ctx.fillRect(x,y,1.2,1.2)}
 for(const r of [150,250,350]){ctx.strokeStyle='#667f8430';ctx.setLineDash([3,7]);ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.stroke()}ctx.setLineDash([]);
 const stroke=(points,color,dash)=>{if(!points.length)return;ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.setLineDash(dash);ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.setLineDash([])};
 stroke(lastPath,'#74899435',[]);if(predict)stroke(preview,'#9abfb175',[3,6]);stroke(path,'#b8f0d3',[]);
 const glow=ctx.createRadialGradient(-12,-15,0,0,0,100);glow.addColorStop(0,'#f7c09b');glow.addColorStop(.45,'#f4a576');glow.addColorStop(.46,'#e68b5030');glow.addColorStop(1,'#e68b5000');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,100,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f6b787';ctx.beginPath();ctx.arc(0,0,RADIUS,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fbd0ac70';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(0,0,71,18,-.5,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#f9cfb4';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('KEPLER / μ 1.8M',0,85);
 targets.forEach((g,i)=>{ctx.strokeStyle=hits[i]?'#e5ffab':'#a8e7cf';ctx.fillStyle=hits[i]?'#c9eeaf25':'#a8e7cf0c';ctx.lineWidth=hits[i]?2.5:1.5;ctx.beginPath();ctx.arc(g.x,g.y,24,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#c5eadb';ctx.font='11px monospace';ctx.fillText(hits[i]?'✓':String(i+1),g.x,g.y+4)});
 const m=missions[index];ctx.fillStyle='#8aa3ae';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('LAUNCH',-m.r,30);
 if(!running&&s.t===0){ctx.strokeStyle='#f5b48b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x+s.vx*.65,s.y+s.vy*.65);ctx.stroke()}
 ctx.save();ctx.translate(s.x,s.y);ctx.rotate(Math.atan2(s.vy,s.vx));ctx.fillStyle='#fff5de';ctx.beginPath();ctx.moveTo(9,0);ctx.lineTo(-6,-5);ctx.lineTo(-3,0);ctx.lineTo(-6,5);ctx.closePath();ctx.fill();ctx.restore();ctx.restore();
 if(history.length){const max=Math.max(...history,1),p=history.filter((_,i)=>i%Math.max(1,Math.floor(history.length/100))===0);$('spark').setAttribute('d',p.map((v,i)=>`${i?'L':'M'}${i*260/Math.max(p.length-1,1)},${33-v/max*29}`).join(' '));}}
function frame(now){const elapsed=Math.min((now-last)/1000||0,.1);last=now;if(running&&!paused&&!document.hidden){acc+=elapsed;while(acc>=DT&&running){tick();acc-=DT}telemetry()}else acc=0;draw();requestAnimationFrame(frame)}
$('speed').oninput=update;$('angle').oninput=update;$('launch').onclick=start;$('reset').onclick=reset;$('pause').onclick=pause;$('ghost').onclick=()=>{predict=!predict;$('ghost').textContent=predict?'Prediction on':'Prediction off';$('ghost').setAttribute('aria-pressed',predict)};$('hint').onclick=()=>{$('hintText').hidden=!$('hintText').hidden;$('hintText').textContent=missions[index].tip};$('solution').onclick=()=>{$('speed').value=missions[index].v;$('angle').value=missions[index].angle;update();$('toast').textContent='A working launch is loaded. Press Launch to test it.'};$('help').onclick=()=>{$('manual').hidden=!$('manual').hidden;$('help').setAttribute('aria-expanded',!$('manual').hidden);if(!$('manual').hidden)$('manual').scrollIntoView({behavior:'auto'})};document.querySelectorAll('[data-m]').forEach(b=>b.onclick=()=>setMission(+b.dataset.m));document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','BUTTON'].includes(document.activeElement.tagName)){e.preventDefault();running?pause():start()}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running&&!paused)pause()});
// Optional browser agent interface; game does not depend on this API.
if(document.modelContext?.registerTool){try {Promise.resolve(document.modelContext.registerTool({name:'get_flight_state',description:'Read the current local simulated flight and gate progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:async input=>{if(input&&Object.keys(input).length)throw new Error('No inputs expected');return {mission:missions[index].name,state:s,gates:hits};}})).catch(()=>{});}catch{}}

update();requestAnimationFrame(frame);
